# Viva — slot D5 (part A): acne & appendageal disorders (8 cases)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — acne chapter (systemic associations,
# drugs for acne, variants, acne scars, sebaceous variations), hidradenitis biologics, eccrine/apocrine glands,
# neutrophilic dermatoses, anti-androgens, occupational acne; facts checked with IADVL 5e and IAA/IADVL acne consensus.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Acne vulgaris", src=f"{PYQ}; {IA} (Acne); Indian Acne Alliance/IADVL consensus; AAD 2024 acne guideline",
 qa=[
 ("Define acne vulgaris.", ["Chronic inflammatory disease of the pilosebaceous unit with comedones, papules, pustules, nodules and cysts on face, chest and back; affects >85% of adolescents; may persist into adulthood (adult female acne)"]),
 ("Explain the pathogenesis.", ["Four key factors: (1) increased sebum production under androgen control (DHT via 5α-reductase type 1 in sebocytes; IGF-1, insulin); (2) follicular hyperkeratinisation of the infundibulum → microcomedone (IL-1α, altered linoleic acid); (3) Cutibacterium acnes (phylotype IA1 dysbiosis) — activates TLR2, inflammasome (IL-1β), lipases produce free fatty acids, biofilm; (4) inflammation — may precede comedone formation (innate immunity, Th17)", "Exposome: high glycaemic-load diet, dairy (skimmed milk), whey protein, stress, cosmetics, occlusion/friction, smoking, pollution, sleep deprivation"]),
 ("Grade acne (Indian/IAA grading).", ["Grade 1: comedones, occasional papules", "Grade 2: papules, comedones, few pustules", "Grade 3: predominant pustules, nodules, abscesses", "Grade 4: mainly cysts, abscesses, widespread scarring (nodulocystic/conglobata)", "Others: Global Acne Grading System (GAGS), Leeds technique, IGA; mild/moderate/severe by lesion counts"]),
 ("Discuss the variants of acne (PYQ).", ["Neonatal (maternal androgens; also neonatal cephalic pustulosis — Malassezia) and infantile acne (3–6 months; persistent — check hyperandrogenism)", "Acne conglobata (nodules, abscesses, interconnecting sinuses, double comedones — men, trunk)", "Acne fulminans (sudden severe ulcerative acne with fever, arthralgia, osteolytic bone lesions, leucocytosis — adolescent boys, sometimes triggered by isotretinoin) — treat with oral steroids then low-dose isotretinoin", "Acne excoriée, acne mechanica (friction — helmets, backpacks), acne cosmetica, pomade acne, occupational (oil acne, chloracne), drug-induced/acneiform (steroids, androgens, lithium, isoniazid, phenytoin, EGFR inhibitors, halogens), tropical acne, acne aestivalis (Mallorca acne), adult female acne (lower face/jawline, hormonal), acne with facial oedema (solid facial oedema/Morbihan), gram-negative folliculitis, SAPHO and PAPA/PASH syndromes"]),
 ("Discuss systemic associations of acne (PYQ).", ["Hyperandrogenism: PCOS (acne + hirsutism + irregular cycles + AN), congenital adrenal hyperplasia (late-onset 21-hydroxylase), androgen-secreting tumours (sudden virilisation), Cushing's, HAIR-AN", "Syndromes: SAPHO (Synovitis, Acne, Pustulosis, Hyperostosis, Osteitis), PAPA (Pyogenic Arthritis, Pyoderma gangrenosum, Acne — PSTPIP1), PASH/PAPASH (with hidradenitis), Apert syndrome (FGFR2 — severe acne), XYY, Behçet's (acneiform)", "Insulin resistance/obesity, eating disorders (bulimia — often with acne excoriée), endocrine — acromegaly"]),
 ("Which investigations are needed?", ["Usually none", "Hormonal work-up for women with signs of hyperandrogenism (irregular menses, hirsutism, sudden onset/resistant acne, androgenic alopecia): total/free testosterone, DHEAS, LH/FSH ratio, 17-OH progesterone, prolactin, fasting glucose/insulin, pelvic ultrasound — ideally day 2–5 of cycle", "Before isotretinoin: fasting lipids, LFT, CBC, pregnancy test (women)"]),
 ("Topical treatment of acne.", ["Retinoids (tretinoin 0.025–0.1%, adapalene 0.1–0.3%, tazarotene, trifarotene 0.005% — RAR-γ selective) — comedolytic, anti-inflammatory; first-line in all grades and for maintenance", "Benzoyl peroxide 2.5–5% — bactericidal, no resistance; combine with antibiotics to prevent resistance", "Topical antibiotics (clindamycin 1%, nadifloxacin, minocycline foam 4%) — never as monotherapy", "Azelaic acid 15–20% (also for PIH), dapsone gel 5–7.5%, clascoterone 1% (topical androgen receptor antagonist), salicylic acid, niacinamide", "Fixed combinations: adapalene–BPO, clindamycin–BPO, clindamycin–tretinoin"]),
 ("Discuss the various drugs used for acne (systemic) (PYQ).", ["Oral antibiotics for moderate–severe inflammatory acne: doxycycline 100 mg/day, minocycline 50–100 mg, sarecycline (narrow-spectrum), azithromycin (pulse; pregnancy alternatives erythromycin), — limit to 3–4 months, always with topical retinoid/BPO", "Hormonal (women): combined oral contraceptives (ethinyl oestradiol + drospirenone/cyproterone acetate/desogestrel), spironolactone 50–100 mg/day, cyproterone acetate, flutamide (hepatotoxicity — rarely), metformin for insulin resistance", "Oral isotretinoin: severe nodulocystic acne, scarring, treatment-resistant moderate acne, acne with psychological distress, gram-negative folliculitis; 0.25–0.5 (up to 1) mg/kg/day; cumulative 120–150 mg/kg or low-dose long-term regimens", "Others: oral zinc, dapsone (acne conglobata), oral steroids (acne fulminans, flares with isotretinoin), ibuprofen"]),
 ("Isotretinoin: mechanism, side effects and monitoring.", ["Mechanism: 13-cis-retinoic acid — shrinks sebaceous glands (~90% sebum reduction), normalises follicular keratinisation, reduces C. acnes indirectly, anti-inflammatory; only drug affecting all 4 pathogenic factors", "Mucocutaneous: cheilitis (universal — compliance marker), xerosis, xerophthalmia, epistaxis, photosensitivity, retinoid dermatitis, paronychia, pyogenic granulomas, telogen effluvium", "Systemic: hypertriglyceridaemia, raised transaminases, myalgia/raised CK, headache, benign intracranial hypertension (avoid tetracyclines together), night-blindness, mood changes/depression (monitor), IBD (unproven), DISH/premature epiphyseal closure (high dose)", "Teratogenicity: craniofacial, cardiac, thymic, CNS defects — two reliable contraception methods 1 month before, during and 1 month after; monthly pregnancy test (iPLEDGE-style)", "Monitoring: lipids and LFT at baseline and 1–2 months, then as needed; mood assessment"]),
 ("Discuss management of acne scars (PYQ).", ["Classification: atrophic — ice-pick (narrow deep <2 mm), boxcar (round/oval sharp walls 1.5–4 mm), rolling (wide undulating); hypertrophic and keloidal scars (chest, back, jawline); Goodman–Baron qualitative grading", "Prevention: early adequate treatment of inflammatory acne", "Atrophic: chemical reconstruction of skin scars (CROSS) with 70–100% TCA for ice-pick; subcision for rolling; punch excision/elevation/grafting for deep boxcar/ice-pick; microneedling ± PRP; fractional ablative (CO2, Er:YAG) and non-ablative (1550 nm) lasers; radiofrequency microneedling; dermal fillers (hyaluronic acid) for rolling; medium-depth peels", "Hypertrophic/keloid: intralesional triamcinolone, silicone, 5-FU, PDL, cryotherapy", "Combination approach and adequate sun protection; wait 6 months after isotretinoin for ablative procedures (traditional caution, evidence weak)"]),
 ("Differential diagnosis.", ["Rosacea (no comedones, flushing, telangiectasia), perioral dermatitis, Pityrosporum folliculitis (monomorphic, itchy), drug-induced acneiform eruptions, folliculitis, milia, syringoma, adenoma sebaceum (angiofibromas), steroid acne, Favre–Racouchot (comedones in sun-damaged skin of elderly), Demodex folliculitis"]),
 ("Write a note on chloracne/oil acne (PYQ).", ["Oil acne: mineral oils/cutting oils in mechanics — comedones, folliculitis on thighs, forearms (where oil-soaked clothes contact)", "Chloracne: halogenated aromatic hydrocarbons (dioxins) — straw-coloured cysts and comedones on malar, retroauricular, scrotum; systemic toxicity marker; very resistant"]),
 ],
 spot=["Comedones = acne (rosacea has none)", "Isotretinoin — teratogen; cheilitis universal", "Ice-pick → TCA CROSS; rolling → subcision"]),

dict(case="Acne excoriée", src=f"{PYQ}; {IA} (Acne; psychocutaneous disorders)",
 qa=[
 ("What is acne excoriée?", ["Psychocutaneous disorder in which (usually mild) acne lesions — or even normal skin — are repetitively picked and squeezed, producing excoriations, crusted erosions, scars and post-inflammatory pigmentation out of proportion to the acne; also 'acné excoriée des jeunes filles' (young women)", "Part of skin-picking (excoriation) disorder in DSM-5 (obsessive-compulsive and related disorders)"]),
 ("Associated psychological conditions.", ["Anxiety, depression, obsessive-compulsive disorder, body dysmorphic disorder, borderline personality traits, eating disorders, stress, perfectionism"]),
 ("Clinical features.", ["Crusted excoriations, erosions, linear scratch marks, atrophic and hypertrophic scars, PIH on face (forehead, cheeks, chin, along hairline), sometimes upper back; few primary acne lesions visible", "Patient often admits picking (unlike dermatitis artefacta)"]),
 ("Differential diagnosis.", ["Dermatitis artefacta (denies self-infliction), neurotic excoriations, acne vulgaris with secondary infection, impetigo, herpes simplex, prurigo, scabies, delusional infestation"]),
 ("Management.", ["Empathetic approach; treat the underlying acne effectively (retinoid, BPO, isotretinoin if needed) to remove the 'trigger'", "Behavioural therapy: habit-reversal training, CBT, mindfulness; occlusive dressings/hydrocolloid patches, keeping nails short", "Psychiatric referral; SSRIs (fluoxetine, sertraline), N-acetylcysteine (glutamate modulator), low-dose antipsychotics in severe cases; treat PIH and scars once picking stops"]),
 ],
 spot=["Excoriations and scars out of proportion to few acne lesions in a young woman — acne excoriée", "Habit-reversal + treat acne + SSRIs/N-acetylcysteine"]),

dict(case="Fox–Fordyce disease", src=f"{PYQ}; {IA} (Disorders of apocrine glands)",
 qa=[
 ("What is Fox–Fordyce disease?", ["Chronic, intensely itchy papular eruption of apocrine gland-bearing areas ('apocrine miliaria') due to keratin plugging of the apocrine duct in the follicular infundibulum with duct rupture; women 13–35 years; worsened by heat, sweating, stress, menstruation; improves in pregnancy and with OCPs/after menopause"]),
 ("Clinical features.", ["Dome-shaped skin-coloured to slightly yellow/hyperpigmented follicular papules in axillae (commonest), areolae, pubic and perineal areas, periumbilical", "Intense itch, decreased apocrine sweating, sparse axillary hair", "Reported after laser hair removal"]),
 ("Discuss apocrine and eccrine glands (PYQ).", ["Eccrine: distributed all over (palms/soles most), open directly on skin, cholinergic sympathetic innervation, merocrine secretion of watery hypotonic sweat — thermoregulation", "Apocrine: axillae, anogenital, areola, ear canal (ceruminous), eyelids (Moll's glands); open into hair follicle above sebaceous duct; adrenergic innervation; functional after puberty; viscous secretion — odour after bacterial action (bromhidrosis)", "Apoeccrine glands: axillae in adults, mixed features — hyperhidrosis"]),
 ("Histopathology.", ["Infundibular hyperkeratosis plugging the apocrine duct, spongiosis of the follicular infundibulum, perifollicular xanthomatous (foamy) macrophages (characteristic), lymphocytic infiltrate, dilated apocrine glands"]),
 ("Differential diagnosis.", ["Lichen nitidus, lichen planus, folliculitis, syringomas, miliaria, Darier's disease, lichen amyloidosis, acanthosis nigricans, hidradenitis suppurativa (early), periductal mastitis (areola)"]),
 ("Treatment.", ["Avoid heat/sweating; loose clothing", "Topical: steroids, clindamycin, tretinoin/adapalene, calcineurin inhibitors (pimecrolimus/tacrolimus), aluminium chloride (limited)", "Systemic: combined OCPs, isotretinoin, botulinum toxin injections, oral antihistamines; procedures — electrocoagulation, fractional laser, liposuction-curettage, surgical excision for severe localised disease"]),
 ],
 spot=["Itchy follicular axillary papules in a young woman, worse with sweating — Fox–Fordyce", "Perifollicular foamy macrophages"]),

dict(case="Hidradenitis suppurativa", src=f"{PYQ}; {IA} (Hidradenitis suppurativa); North American/European HS guidelines",
 qa=[
 ("Define hidradenitis suppurativa (HS).", ["Chronic, recurrent, inflammatory, debilitating follicular occlusive disease of intertriginous apocrine gland-bearing areas, presenting with painful deep nodules, abscesses, draining tunnels (sinus tracts) and scarring, usually after puberty (acne inversa)", "Diagnosis: typical lesions (nodules, tunnels, scars) + typical sites (axillae, groin, inframammary, perineal, buttocks) + chronicity/recurrence (≥2 episodes in 6 months)"]),
 ("Pathogenesis.", ["Primary event is follicular occlusion (infundibular hyperkeratosis) → dilation and rupture of follicle → spillage of keratin/bacteria → intense innate inflammation (IL-1β, TNF-α, IL-17, IL-23) → abscesses and epithelialised tunnels", "Risk factors: obesity, smoking (strong), mechanical friction, genetic (γ-secretase genes — NCSTN, PSENEN, PSEN1; ~30–40% family history), hormones (premenstrual flares), metabolic syndrome", "Follicular occlusion tetrad: HS, acne conglobata, dissecting cellulitis of scalp, pilonidal sinus"]),
 ("Severity staging.", ["Hurley staging: I — single/multiple abscesses without tunnels or scarring; II — recurrent abscesses with tunnels and scarring, widely separated; III — diffuse/near-diffuse involvement with interconnected tunnels and abscesses across an entire area", "Others: IHS4 (nodules ×1 + abscesses ×2 + draining tunnels ×4), Sartorius score, HiSCR (≥50% reduction in abscess + nodule count without increase in abscesses/draining tunnels) — trial outcome"]),
 ("Associated conditions.", ["Metabolic syndrome, diabetes, obesity, PCOS, inflammatory bowel disease (Crohn's), spondyloarthritis, pyoderma gangrenosum (PASH/PAPASH syndromes), depression, anxiety, Down syndrome, Dowling–Degos disease (PSENEN), SCC in chronic gluteal/perineal HS (men, smokers)"]),
 ("Differential diagnosis.", ["Furuncles/carbuncles (acute, not recurrent at same flexural sites, no tunnels), epidermoid/pilonidal cysts, Crohn's disease (perianal fistulae), lymphogranuloma venereum, scrofuloderma, actinomycosis, granuloma inguinale, Bartholin abscess, cutaneous TB, anal fistula"]),
 ("Discuss treatment including biologics (PYQ).", ["General: weight loss, smoking cessation, loose clothing, antiseptic washes (chlorhexidine, BPO), pain control, psychological support, warm compresses, dressings", "Hurley I/mild: topical clindamycin 1% twice daily, resorcinol 15% peel, intralesional triamcinolone 10 mg/ml for acute nodules; oral tetracyclines (doxycycline 100 mg BD for 12 weeks)", "Moderate: clindamycin 300 mg BD + rifampicin 300 mg BD for 10–12 weeks; metformin, zinc gluconate, anti-androgens (spironolactone, OCP) in women; acitretin (men), dapsone", "Moderate–severe: biologics — adalimumab (160 mg week 0, 80 mg week 2, then 40 mg weekly or 80 mg alternate weeks — first approved), secukinumab (IL-17A), bimekizumab (IL-17A/F) — approved for HS; infliximab, ustekinumab, anakinra (off-label); JAK inhibitors (upadacitinib) in trials", "Surgery: incision and drainage (acute relief only), deroofing of tunnels (preferred for Hurley II), STEEP, wide excision with healing by secondary intention or flaps/grafts (Hurley III), CO2 laser excision; laser hair removal (Nd:YAG) reduces recurrences"]),
 ("Histopathology.", ["Follicular plugging and dilatation, ruptured follicles with neutrophilic abscesses, granulomas, epithelialised sinus tracts, fibrosis; apocrine involvement is secondary"]),
 ("Prognosis.", ["Chronic relapsing; marked impact on quality of life (DLQI often very high); early recognition (average diagnostic delay 7–10 years) and early systemic/biologic therapy prevent tunnels and scarring"]),
 ],
 spot=["Recurrent painful nodules + double comedones + tunnels in axillae/groin — HS", "Hurley staging; adalimumab, secukinumab, bimekizumab", "Deroofing for tunnels"]),

dict(case="Miliaria", src=f"{PYQ}; {IA} (Disorders of eccrine sweat glands)",
 qa=[
 ("What is miliaria?", ["Eruption caused by obstruction of eccrine sweat ducts with leakage of sweat into the epidermis/dermis — common in hot humid climates, neonates (immature ducts), febrile patients, occlusive clothing/dressings, bedridden patients"]),
 ("Classify miliaria by the level of duct obstruction.", ["Miliaria crystallina (sudamina): obstruction in stratum corneum — tiny clear superficial dew-drop vesicles without inflammation, rupture easily; neonates, fever", "Miliaria rubra (prickly heat): intra-epidermal (spinous layer) — itchy/prickly red papules and papulovesicles on trunk, flexures, neck; commonest", "Miliaria pustulosa: miliaria rubra with sterile/superficial pustules", "Miliaria profunda: dermo-epidermal junction — non-itchy skin-coloured firm papules after repeated episodes in tropics; associated with anhidrosis and heat exhaustion ('tropical anhidrotic asthenia')"]),
 ("Pathogenesis.", ["Excess sweating + occlusion → maceration of stratum corneum → keratin plugs and PAS-positive material (extracellular polysaccharide from Staphylococcus epidermidis biofilm) block the duct → sweat leaks out → inflammation"]),
 ("Discuss the composition of sweat (PYQ).", ["Eccrine sweat is hypotonic: water (~99%), sodium chloride (Na 10–90 mmol/L — reabsorbed in the duct), potassium, urea, lactate, ammonia, bicarbonate, amino acids, antimicrobial peptides (dermcidin, cathelicidin), immunoglobulin A; pH 4–6.8", "Sweat chloride >60 mmol/L in cystic fibrosis (diagnostic sweat test)"]),
 ("Differential diagnosis.", ["Neonates: erythema toxicum neonatorum, transient neonatal pustular melanosis, neonatal acne/cephalic pustulosis, candidiasis, herpes, staph folliculitis, impetigo", "Adults: folliculitis, Pityrosporum folliculitis, Grover's disease (transient acantholytic dermatosis — sweat-induced), insect bites, varicella (crystallina), drug eruption (AGEP)"]),
 ("Treatment.", ["Cool environment, air conditioning, fans, loose cotton clothing, reduce sweating and occlusion, frequent cool baths", "Calamine lotion, mild topical steroids for rubra, anhydrous lanolin (prevents duct blockage in profunda), menthol/camphor lotions; antiseptics/antibiotics for pustulosa", "Avoid heavy creams/ointments; treat fever"]),
 ],
 spot=["Dew-drop vesicles in febrile neonate — miliaria crystallina", "Prickly red papules in summer — miliaria rubra"]),

dict(case="Perioral dermatitis", src=f"{PYQ}; {IA} (Rosacea and related disorders)",
 qa=[
 ("What is perioral dermatitis?", ["Common facial eruption of young women (and children) with small erythematous papules, papulovesicles and pustules on a red, scaly background around the mouth, sparing a narrow zone at the vermilion border; may involve nasolabial folds and periocular areas (periorificial dermatitis)"]),
 ("Causes/triggers.", ["Topical (and inhaled/nasal) corticosteroids — the most important; heavy moisturisers/foundation, fluorinated toothpaste, cosmetics, sunscreens; OCPs, hormonal changes; Demodex, Candida, fusobacteria (unclear); barrier dysfunction/atopy", "Granulomatous periorificial dermatitis (childhood — Afro-Caribbean children, yellow-brown papules; FACE — facial Afro-Caribbean childhood eruption)"]),
 ("Differential diagnosis.", ["Rosacea (older, central face, flushing, telangiectasia), acne (comedones), seborrhoeic dermatitis (greasy scale, nasolabial), contact dermatitis (allergic — patch test), steroid rosacea, Demodex folliculitis, lupus miliaris disseminatus faciei, sarcoidosis (granulomatous form), impetigo, lip-licking dermatitis"]),
 ("Histopathology.", ["Spongiotic dermatitis with perifollicular lymphohistiocytic infiltrate, sometimes rosacea-like; granulomatous variant shows non-caseating granulomas around follicles"]),
 ("Treatment.", ["'Zero therapy': stop all topical steroids and facial cosmetics (warn about rebound flare for 1–2 weeks; taper from potent to hydrocortisone if severe), use gentle cleanser", "Topical: metronidazole 0.75–1% gel/cream, erythromycin, clindamycin, azelaic acid 15–20%, pimecrolimus/tacrolimus (also for steroid withdrawal), ivermectin 1%", "Oral: doxycycline 40–100 mg or minocycline for 6–12 weeks (adults); erythromycin/azithromycin in children and pregnancy; isotretinoin (resistant)", "Recurrence is common if steroids are restarted"]),
 ],
 spot=["Papulopustules around the mouth sparing the vermilion border in a steroid-cream user — perioral dermatitis", "Zero therapy + doxycycline"]),

dict(case="Pyoderma faciale (rosacea fulminans)", src=f"{PYQ}; {IA} (Rosacea)",
 qa=[
 ("What is rosacea fulminans (pyoderma faciale)?", ["Sudden, severe, explosive variant of rosacea in young women (20–40 y) with confluent nodules, pustules, abscesses and draining sinuses on the central face on a background of intense erythema; no comedones; usually no systemic symptoms (unlike acne fulminans)"]),
 ("Triggers / associations.", ["Pregnancy, emotional stress, OCP/ hormonal changes, inflammatory bowel disease (Crohn's, UC), high-dose vitamin B6/B12, interferon/EGFR inhibitors, history of mild rosacea/flushing"]),
 ("Clinical features.", ["Rapid-onset (days–weeks) painful, coalescing papules, pustules and fluctuant nodules on cheeks, chin, forehead, nose; marked erythema/oedema; may scar", "Fever or arthralgia are uncommon (consider acne fulminans or neutrophilic dermatosis if present)"]),
 ("Classify neutrophilic dermatoses (PYQ).", ["Sweet syndrome, pyoderma gangrenosum, Behçet's, neutrophilic eccrine hidradenitis, subcorneal pustular dermatosis, bowel-associated dermatosis–arthritis syndrome, rheumatoid neutrophilic dermatitis, erythema elevatum diutinum, neutrophilic dermatosis of dorsal hands, autoinflammatory syndromes (PAPA, PASH, SAPHO), rosacea fulminans/acne fulminans (overlap)"]),
 ("Differential diagnosis.", ["Acne fulminans (adolescent boys, trunk, systemic symptoms, comedones), acne conglobata, gram-negative folliculitis, halogenoderma (iodides/bromides), deep fungal infection, cutaneous TB, pyoderma gangrenosum, Sweet syndrome"]),
 ("Treatment.", ["Oral prednisolone 0.5–1 mg/kg/day for 1–2 weeks to settle inflammation, then add oral isotretinoin 0.2–0.5 mg/kg/day for 3–4 months while tapering steroid", "Topical/intralesional steroids, gentle care, drainage of fluctuant nodules", "Pregnancy: oral steroids, azithromycin/erythromycin, topical metronidazole/azelaic acid; isotretinoin only after delivery (contraception)", "Treat underlying IBD"]),
 ],
 spot=["Explosive central facial nodules/abscesses on red background in a young woman, no comedones — rosacea fulminans", "Steroids first, then isotretinoin"]),

dict(case="Rosacea", src=f"{PYQ}; {IA} (Rosacea); ROSCO 2017/2019 phenotype approach",
 qa=[
 ("Define rosacea.", ["Chronic inflammatory disease of central facial skin with flushing, persistent erythema, telangiectasia, papules, pustules and phymatous changes; adults 30–50 y, fair skin (under-recognised in dark skin), women more (men more phymas)"]),
 ("Diagnostic phenotypes (ROSCO approach).", ["Diagnostic (1 is enough): persistent centrofacial erythema with periodic intensification; phymatous changes", "Major (2 needed if no diagnostic): flushing/transient erythema, inflammatory papules and pustules, telangiectasia, ocular manifestations (lid margin telangiectasia, blepharitis, keratitis, conjunctivitis, scleritis)", "Minor: burning, stinging, oedema, dryness", "Older subtypes (NRS 2002): erythematotelangiectatic, papulopustular, phymatous, ocular; variant — granulomatous"]),
 ("Explain the pathogenesis.", ["Neurovascular dysregulation (TRPV1/TRPA1 channels — heat, spices, alcohol trigger flushing; PACAP, CGRP)", "Innate immune dysfunction — high kallikrein-5 cleaves cathelicidin into pro-inflammatory LL-37; TLR2 upregulated; mast cells (MMP-9)", "Demodex folliculorum overgrowth and Bacillus oleronius; UV damage, matrix degeneration", "Triggers: sun, heat, hot drinks, spicy food, alcohol, exercise, stress, cold wind, topical steroids, cosmetics"]),
 ("Clinical features of phymas.", ["Rhinophyma (bulbous nose — men, sebaceous hyperplasia and fibrosis), gnathophyma (chin), metophyma (forehead), otophyma (ears), blepharophyma (eyelids)"]),
 ("Ocular rosacea.", ["In up to 50%; may precede skin; meibomian gland dysfunction, blepharitis, chalazia, conjunctival hyperaemia, dry eye, keratitis, corneal ulcers/perforation — refer to ophthalmology; treat with lid hygiene, doxycycline, cyclosporine eye drops"]),
 ("Differential diagnosis.", ["Acne vulgaris (comedones, younger), SLE (malar rash spares nasolabial folds, no pustules, systemic), seborrhoeic dermatitis (scale), perioral dermatitis, steroid-induced rosacea, carcinoid syndrome/mastocytosis (flushing), photosensitivity, Demodex folliculitis, polycythaemia, dermatomyositis, sarcoidosis/lupus miliaris disseminatus faciei (granulomatous)"]),
 ("Treatment by phenotype.", ["General: avoid triggers, gentle skin care, daily broad-spectrum sunscreen, green-tinted cosmetics", "Persistent erythema: topical brimonidine 0.33% gel or oxymetazoline 1% cream (α-agonist vasoconstrictors — rebound erythema risk)", "Telangiectasia/erythema: PDL 585/595 nm, IPL, KTP laser", "Papules/pustules: topical ivermectin 1% (anti-Demodex — very effective), metronidazole 0.75–1%, azelaic acid 15%, minocycline foam 1.5%; oral doxycycline 40 mg modified-release (sub-antimicrobial) or 100 mg, minocycline; low-dose isotretinoin (0.1–0.3 mg/kg) for refractory", "Flushing: β-blockers (carvedilol, propranolol), clonidine, botulinum toxin, SSRIs (paroxetine)", "Phymas: isotretinoin early; surgical — CO2/Er:YAG laser resurfacing, electrosurgery, decortication", "Ocular: lid hygiene, doxycycline, topical cyclosporine, ophthalmology"]),
 ("What is steroid-induced rosacea?", ["Rosacea-like eruption/flare with erythema, telangiectasia, papulopustules and atrophy after prolonged topical steroid use on the face (common in India — fairness creams with steroid); rebound on stopping; treat by stopping steroid (taper), tacrolimus, doxycycline, ivermectin"]),
 ],
 spot=["Central facial erythema + flushing + papulopustules without comedones — rosacea", "Ivermectin 1% cream; brimonidine/oxymetazoline for erythema", "Rhinophyma — men"]),
]
